const clientName = $('Webhook').item.json.client_name;
const rows = items;

const match = rows.find(item => item.json.client_name === clientName);
if (!match) {
  throw new Error(`Client '${clientName}' not found in Google Sheets`);
}

return [{
  json: {
    client_name: match.json.client_name,
    website_url: match.json.website_url,
    sitemap_url: match.json.sitemap_url,
    drive_folder_id: match.json.drive_folder_id || '',
    articles_folder_id: match.json.articles_folder_id || '',
    keyword: $('Webhook').item.json.keyword,
    word_count: parseInt($('Webhook').item.json.word_count) || 1500,
    tone: $('Webhook').item.json.tone || 'profesional'
  }
}];

// Normalize output after folder creation
return [{
  json: {
    client_name: $('Code Find Client').item.json.client_name,
    website_url: $('Code Find Client').item.json.website_url,
    keyword: $('Code Find Client').item.json.keyword,
    word_count: $('Code Find Client').item.json.word_count,
    tone: $('Code Find Client').item.json.tone,
    drive_folder_id: $('Drive Create Root Folder').item.json.id,
    articles_folder_id: $('Drive Create 01 Articles').item.json.id
  }
}];

const results = $json.organic_results || [];
const clientData = $('Merge Folder Branches').item.json;

// Filter: no youtube, no ads, organic only
const filtered = results
  .filter(r => r.link && !r.link.includes('youtube.com') && !r.link.includes('youtu.be'))
  .slice(0, 3)
  .map((r, i) => ({
    ref_index: i + 1,
    title: r.title || '',
    url: r.link || '',
    snippet: r.snippet || '',
    client_name: clientData.client_name,
    website_url: clientData.website_url,
    keyword: clientData.keyword,
    word_count: clientData.word_count,
    tone: clientData.tone,
    drive_folder_id: clientData.drive_folder_id,
    articles_folder_id: clientData.articles_folder_id
  }));

if (filtered.length === 0) {
  throw new Error('SerpAPI returned no organic results for keyword: ' + clientData.keyword);
}

return filtered.map(f => ({ json: f }));

// Extract scraped data and attach metadata from the loop item
const scrape = $json;
const refIndex = $('Loop Refs').item.json.ref_index;
const title = $('Loop Refs').item.json.title;
const url = $('Loop Refs').item.json.url;

return [{
  json: {
    ref_index: refIndex,
    ref_title: title,
    ref_url: url,
    ref_markdown: scrape.data?.markdown || scrape.markdown || '',
    // Pass-through client data
    client_name: $('Loop Refs').item.json.client_name,
    website_url: $('Loop Refs').item.json.website_url,
    keyword: $('Loop Refs').item.json.keyword,
    word_count: $('Loop Refs').item.json.word_count,
    tone: $('Loop Refs').item.json.tone,
    drive_folder_id: $('Loop Refs').item.json.drive_folder_id,
    articles_folder_id: $('Loop Refs').item.json.articles_folder_id
  }
}];

// Restructure aggregated references into a single object
const allRefs = $json.data || [];

const refs = {};
allRefs.forEach(ref => {
  const i = ref.ref_index;
  refs[`ref_${i}_title`] = ref.ref_title || '';
  refs[`ref_${i}_url`] = ref.ref_url || '';
  refs[`ref_${i}_markdown`] = (ref.ref_markdown || '').slice(0, 8000); // cap at 8k chars
});

const first = allRefs[0] || {};

return [{
  json: {
    ...refs,
    client_name: first.client_name,
    website_url: first.website_url,
    keyword: first.keyword,
    word_count: first.word_count,
    tone: first.tone,
    drive_folder_id: first.drive_folder_id,
    articles_folder_id: first.articles_folder_id
  }
}];

// Store crawl ID for polling and pass through all data
const crawlResponse = $json;
const prevData = $('Code Combine References').item.json;

return [{
  json: {
    ...prevData,
    crawl_id: crawlResponse.id || crawlResponse.jobId || '',
    crawl_status: crawlResponse.status || 'started'
  }
}];

const crawlResult = $json;
const prevData = $('Code Store Crawl ID').item.json;
const keyword = prevData.keyword.toLowerCase();

// Get pages from crawl result
const pages = crawlResult.data || [];

// TOFU patterns (blog/educational)
const tofuPatterns = ['/blog/', '/artikel/', '/panduan/', '/tips/', '/cara/', '/apa-itu/', '/pengertian/', '/tutorial/'];
// BOFU patterns (money/conversion)
const bofuPatterns = ['/produk/', '/layanan/', '/jasa/', '/harga/', '/paket/', '/beli/', '/order/', '/hubungi/'];

const scorePage = (page) => {
  let score = 0;
  const url = (page.url || page.metadata?.url || '').toLowerCase();
  const title = (page.metadata?.title || '').toLowerCase();
  const description = (page.metadata?.description || '').toLowerCase();
  const content = (page.markdown || '').toLowerCase();

  if (title.includes(keyword)) score += 5;
  if (url.includes(keyword.replace(/\s+/g, '-'))) score += 3;
  if (description.includes(keyword)) score += 2;
  if (content.includes(keyword)) score += 1;
  return score;
};

const classifyPage = (page) => {
  const url = (page.url || page.metadata?.url || '').toLowerCase();
  for (const p of tofuPatterns) if (url.includes(p)) return 'TOFU';
  for (const p of bofuPatterns) if (url.includes(p)) return 'BOFU';
  return 'OTHER';
};

const generateAnchors = (title, keyword) => {
  const kw = keyword || '';
  const words = kw.split(' ');
  const lsi = words.length > 1 ? words[0] + ' terbaik' : kw + ' terpercaya';
  return [
    kw,
    lsi,
    'Pelajari lebih lanjut'
  ];
};

const scored = pages.map(page => ({
  url: page.url || page.metadata?.url || '',
  title: page.metadata?.title || '',
  type: classifyPage(page),
  score: scorePage(page),
  anchors: generateAnchors(page.metadata?.title || '', prevData.keyword)
}));

const tofu = scored
  .filter(p => p.type === 'TOFU' && p.url)
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

const bofu = scored
  .filter(p => p.type === 'BOFU' && p.url)
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

const formatLinks = (links) => links.map((l, i) =>
  `${i+1}. ${l.title}\n   URL: ${l.url}\n   Anchor suggestions: ${l.anchors.join(' | ')}`
).join('\n\n');

return [{
  json: {
    ...prevData,
    blog_links_text: formatLinks(tofu),
    money_links_text: formatLinks(bofu),
    internal_links_count: tofu.length + bofu.length,
    tofu_links: tofu,
    bofu_links: bofu
  }
}];

