  Array.isArray(metadata.alt_texts) && metadata.alt_texts.length >= 1 && metadata.excerpt;

return [{
  json: {
    ...prevData,
    metadata_valid: !!isValid,
    metadata: isValid ? metadata : null,
    metadata_raw: rawText
  }
}];

