const response = $json;
const prevData = $('Code Validate Article').item.json;

let articleText = '';
try {
  articleText = response.content[0].text || '';
} catch(e) {
  articleText = prevData.article_text || '';
}

return [{
  json: {
    ...prevData,
    article_text: articleText,
    article_valid: true
  }
}];

const data = $json;
const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
const keyword = data.keyword || '';
const articleText = data.article_text || '';
const metadata = data.metadata || {};

// Parse sections from article
const extractSection = (text, startTag, endTag) => {
  const start = text.indexOf(startTag);
  if (start === -1) return '';
  const contentStart = start + startTag.length;
  const end = endTag ? text.indexOf(endTag, contentStart) : text.length;
  return text.slice(contentStart, end === -1 ? text.length : end).trim();
};

const publisherBox = extractSection(articleText, '[PUBLISHER BOX]', '[JUDUL ARTIKEL]');
const judul = extractSection(articleText, '[JUDUL ARTIKEL]', '[ISI ARTIKEL]').trim();
const isi = extractSection(articleText, '[ISI ARTIKEL]', '[SITASI/REFERENSI]');
const sitasi = extractSection(articleText, '[SITASI/REFERENSI]', null);

// Build HTML content for Google Docs
const publisherBoxHtml = `<table style="width:100%;background-color:#f5f5f5;border:1px solid #ddd;padding:10px;font-family:monospace;font-size:12px;"><tr><td><pre>${publisherBox.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre></td></tr></table>`;

const isiHtml = isi
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\*(.+?)\*/g, '<em>$1</em>')
  .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2">$1</a>')
  .replace(/^- (.+)$/gm, '<li>$1</li>')
  .replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>')
  .replace(/\n\n/g, '</p><p>')
  .replace(/^(?!<[hul])/gm, '');

const sitasiHtml = sitasi
  .split('\n')
  .filter(l => l.trim())
  .map(l => `<p>${l.trim()}</p>`)
  .join('');

const fullHtml = `${publisherBoxHtml}<h1>${judul}</h1><div>${isiHtml}</div><hr><h2>Sitasi &amp; Referensi</h2>${sitasiHtml}`;

const docTitle = `${today}_${keyword.replace(/\s+/g, '-').toLowerCase()}`;

return [{
  json: {
    ...data,
    doc_title: docTitle,
    doc_html: fullHtml,
    judul_artikel: judul,
    preview_text: isi.slice(0, 200),
    sitasi_text: sitasi
  }
}];

const driveResponse = $json;
const prevData = $('Code Build Doc Content').item.json;

const docId = driveResponse.id || '';
const docUrl = docId ? `https://docs.google.com/document/d/${docId}/edit` : '';

// Parse references for response
const references = [
  { title: prevData.ref_1_title || '', url: prevData.ref_1_url || '' },
  { title: prevData.ref_2_title || '', url: prevData.ref_2_url || '' },
  { title: prevData.ref_3_title || '', url: prevData.ref_3_url || '' }
].filter(r => r.url);

return [{
  json: {
    status: 'success',
    google_docs_url: docUrl,
    doc_id: docId,
    doc_title: prevData.doc_title,
    metadata: {
      slug: prevData.metadata?.slug || '',
      meta_title: prevData.metadata?.meta_title || '',
      meta_description: prevData.metadata?.meta_description || ''
    },
    preview: prevData.preview_text || '',
    internal_links_count: prevData.internal_links_count || 0,
    references: references,
    word_count_actual: prevData.article_word_count || 0,
    keyword: prevData.keyword
  }
}];
